const searchTasks = `-- name: SearchTasks :many
SELECT id, title, updated_at FROM tasks
WHERE deleted_at IS NULL
  AND EXISTS (
      SELECT 1 FROM task_lists tl
      WHERE tl.id = tasks.list_id AND tl.list_kind = 'tasks'
  )
  AND title ILIKE '%' || $1::text || '%'
ORDER BY updated_at DESC
LIMIT $2
`

type SearchTasksParams struct {
	Query    string
	RowLimit int32
}

type SearchTasksRow struct {
	ID        string
	Title     string
	UpdatedAt time.Time
}

func (q *Queries) SearchTasks(ctx context.Context, arg SearchTasksParams) ([]SearchTasksRow, error) {
	rows, err := q.db.Query(ctx, searchTasks, arg.Query, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchTasksRow{}
	for rows.Next() {
		var i SearchTasksRow
		if err := rows.Scan(&i.ID, &i.Title, &i.UpdatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

