const updateTask = `-- name: UpdateTask :one
UPDATE tasks SET
    title       = coalesce($1, title),
    description = CASE WHEN $2::bool THEN NULL
                       ELSE coalesce($3, description) END,
    status      = coalesce($4, status),
    priority    = coalesce($5, priority),
    due_date    = CASE WHEN $6::bool THEN NULL
                       WHEN $7::timestamptz IS NOT NULL THEN NULL
                       ELSE coalesce($8, due_date) END,
    due_at      = CASE WHEN $9::bool THEN NULL
                       WHEN $8::date IS NOT NULL THEN NULL
                       ELSE coalesce($7, due_at) END,
    due_timezone = CASE
        WHEN $6::bool AND $9::bool THEN NULL
        ELSE coalesce($10, due_timezone) END,
    scheduled_start_at = CASE WHEN $11::bool THEN NULL
                              ELSE coalesce($12, scheduled_start_at) END,
    scheduled_end_at   = CASE WHEN $13::bool
                                OR $11::bool THEN NULL
                              ELSE coalesce($14, scheduled_end_at) END,
    scheduled_timezone = CASE WHEN $11::bool THEN NULL
                              ELSE coalesce($15, scheduled_timezone) END,
    estimated_minutes  = CASE WHEN $16::bool THEN NULL
                              ELSE coalesce($17, estimated_minutes) END,
    focus_date  = CASE WHEN $18::bool THEN NULL
                       ELSE coalesce($19, focus_date) END,
    list_id     = coalesce($20, list_id),
    project_id  = CASE WHEN $21::bool THEN NULL
                       ELSE coalesce($22, project_id) END,
    reminders   = CASE WHEN $23::bool THEN '[]'::jsonb
                       ELSE coalesce($24, reminders) END,
    quantity_text = CASE WHEN $25::bool THEN NULL
                         ELSE coalesce($26, quantity_text) END,
    -- 品类由服务端重新分类后传入，不接受客户端直接指定。
    shopping_category = coalesce($27, shopping_category),
    -- 完成时间由 Domain 计算后传入，保持与 status 一致。
    completed_at = CASE WHEN $28::bool THEN $29
                        ELSE completed_at END,
    updated_at  = now(),
    version     = version + 1
WHERE id = $30 AND deleted_at IS NULL
RETURNING id, user_id, title, description, status, priority, due_date, due_at, due_timezone, scheduled_start_at, scheduled_end_at, scheduled_timezone, estimated_minutes, focus_date, list_id, project_id, reminders, completed_at, created_by, provenance_refs, created_at, updated_at, deleted_at, version, quantity_text, shopping_category
`

